abstract class UPSItemBasePriceCalcJob extends RunBaseBatch
{
    ItemId                      itemId;
    InventDimId                 inventDimId;
    UPSBasePriceVersionId       versionId;
    InventSiteId                siteId;
    TransDate                   calcDate;

    UPSCalcBasePriceVersionUpdate calcBasePriceVersionUpdate;

    boolean                     showItemPriceCalcFormAfterRun;

    // Transfer cost price
    NoYes                       purchPriceTransfer;
    NoYes                       salesPriceTransfer;
    NoYes                       costPriceTransfer;

    // Where used update
    UPSBasePriceCalcWhereUsedUpdate      basePriceCalcWhereUsedUpdate;

}

Method.Source:
InventDimId parmInventDimId(InventDimId _inventDimId = inventDimId)
{
    inventDimId = _inventDimId;

    return inventDimId;
}

ItemId parmItemId(ItemId _itemId = itemId)
{
    itemId = _itemId;
    return itemId;
}

UPSBasePriceVersionId parmVersionId(UPSBasePriceVersionId _versionId = versionId)
{
    versionId = _versionId;
    return versionId;
}

public InventSiteId parmSiteId(InventSiteId _siteId = siteId)
{
    siteId = _siteId;

    return siteId;
}

TransDate parmCalcDate(TransDate newCalcDate = calcDate)
{
    calcDate = newCalcDate;
    return calcDate;
}

public boolean parmShowItemPriceCalcFormAfterRun(boolean _showItemPriceCalcFormAfterRun = showItemPriceCalcFormAfterRun)
{
    showItemPriceCalcFormAfterRun = _showItemPriceCalcFormAfterRun;
    return showItemPriceCalcFormAfterRun;
}

NoYes parmPurchPriceTransfer(NoYes _purchPriceTransfer = purchPriceTransfer)
{
    purchPriceTransfer = _purchPriceTransfer;
    return purchPriceTransfer;
}

NoYes parmSalesPriceTransfer(NoYes _salesPriceTransfer = salesPriceTransfer)
{
    salesPriceTransfer = _salesPriceTransfer;
    return salesPriceTransfer;
}

NoYes parmCostPriceTransfer(NoYes _costPriceTransfer = costPriceTransfer)
{
    costPriceTransfer = _costPriceTransfer;
    return costPriceTransfer;
}

public UPSBasePriceCalcWhereUsedUpdate parmBasePriceCalcWhereUsedUpdate(UPSBasePriceCalcWhereUsedUpdate _basePriceCalcWhereUsedUpdate = basePriceCalcWhereUsedUpdate)
{
    basePriceCalcWhereUsedUpdate = basePriceCalcWhereUsedUpdate;

    return basePriceCalcWhereUsedUpdate;
}

InventDimId inventDimIdSite()
{
    InventDim   inventDimSite;

    inventDimSite.InventSiteId = this.parmSiteId();
    return InventDim::findOrCreate(inventDimSite).InventDimId;
}

boolean showItem()
{
    return true;
}

void new()
{
    super();

    costPriceTransfer           = NoYes::Yes;
    versionId                   = '';
    calcBasePriceVersionUpdate    = UPSCalcBasePriceVersionUpdate::Overwrite;

}

public Object dialog()
{
    return this.dialogInternal(Dialog::newFormnameRunbase(formStr(UPSItemBasePriceCalcDialog), this));
}

void run()
{
    this.runBasePriceCalculation();
}

protected void runBasePriceCalculation()
{

}

static UPSItemBasePriceCalcJob construct(Args args)
{
    return null;
}

static ClassDescription description()
{
    return "@SYS343262";
}

static void main(Args args)
{
    if (!args)
    {
        throw error(strFmt("@SYS23686",formStr(BOMCalcTable)));
    }

    UPSItemBasePriceCalcJob basePriceCalc = UPSItemBasePriceCalcJob::newBasePriceCalcJobFromArgs(args);

    if (basePriceCalc.prompt())
    {
        using (SysErrorMessageHelpScope scope = SysErrorMessageHelpScope::newErrorContext(args))
        {
            basePriceCalc.runOperation();
        }

        basePriceCalc.openItemPriceCalcForm(args.caller());
    }
}

protected void openItemPriceCalcForm(Object _caller)
{
    if (this.parmShowItemPriceCalcFormAfterRun())
    {
        Args argsItemPriceCalcForm = new Args();
        argsItemPriceCalcForm.caller(_caller);
        argsItemPriceCalcForm.record(InventTable::find(this.parmItemId()));

        FormRun formRunItemPriceCalcForm = new MenuFunction(menuitemDisplayStr(InventItemPrice), MenuItemType::Display).create(argsItemPriceCalcForm);
        formRunItemPriceCalcForm.run();
    }
}

static UPSItemBasePriceCalcJob newBasePriceCalcJobFromArgs(Args args)
{
    UPSItemBasePriceCalcJob         basePriceCalc;
    UPSIItemBasePriceCalcIRunnable   calcFormRun;

    calcFormRun = args.caller();
    basePriceCalc = UPSItemBasePriceCalcJob::newAll(calcFormRun.basePriceVersion());

    return basePriceCalc;
}

static UPSItemBasePriceCalcJob newAll(UPSBasePriceVersion _basePriceVersion)
{
    UPSItemBasePriceCalcJob_All  basePriceCalc = UPSItemBasePriceCalcJob_All::construct();

    basePriceCalc.getLast();
    basePriceCalc.parmVersionId(_basePriceVersion.VersionId);
    basePriceCalc.parmSiteId(_basePriceVersion.InventSiteId);
    basePriceCalc.parmInventDimId(basePriceCalc.inventDimIdSite());

    return basePriceCalc;
}
